const word = typeof $json.body?.word === 'string' ? $json.body.word.trim() : '';
const valid = word.length > 0 && word.length <= 100 && /^[a-zA-Z]+(?:[ '\u2019-][a-zA-Z]+)*$/.test(word);
if (valid) {
  const date = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Seoul', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
  const state = $getWorkflowStaticData('global');
  if (state.wordMeaningQuota?.date !== date) state.wordMeaningQuota = { date, count: 0 };
  if (state.wordMeaningQuota.count >= 200) {
    return [{ json: { valid: false, statusCode: 429, body: { error: '오늘의 단어 의미 생성 한도(200개)를 모두 사용했습니다. 내일 다시 이용해주세요.' } } }];
  }
  state.wordMeaningQuota.count += 1;
}
return [{ json: valid ? { valid, word } : { valid, statusCode: 400, body: { error: '100자 이내의 영단어나 영어 표현을 입력해주세요.' } } }];

const fail = (statusCode, error) => [{ json: { statusCode, body: { error } } }];
if ($json.error) return fail(502, 'AI 서비스 연결에 실패했습니다. n8n의 API 키와 실행 기록을 확인해주세요.');
if ($json.status !== 'completed') return fail(502, 'AI 응답이 완료되지 않았습니다. 다시 시도해주세요.');
try {
  const text = ($json.output || []).flatMap(item => item.content || []).filter(item => item.type === 'output_text').map(item => item.text).join('');
  const result = JSON.parse(text);
  if (typeof result.found !== 'boolean' || typeof result.meaning !== 'string' || typeof result.example !== 'string') throw new Error('Invalid response');
  if (!result.found) return fail(422, '뜻을 찾을 수 없습니다. 영단어 철자를 확인해주세요.');
  if (!result.meaning.trim() || !result.example.trim()) throw new Error('Empty response');
  return [{ json: { statusCode: 200, body: { word: $('Validate input').first().json.word, meaning: result.meaning.trim(), example: result.example.trim() } } }];
} catch {
  return fail(502, 'AI 응답을 처리하지 못했습니다. 다시 시도해주세요.');
}
